/**
 * Helpers de alertas con SweetAlert2, pre-configurados con el branding de
 * Forward Contabilidad (morado #6B2C8F) y mensajes en español de Costa Rica.
 *
 * Usalos en vez de `window.alert` o `window.confirm` para tener consistencia
 * visual y que los mensajes no se vean como un alert nativo del navegador
 * (que rompe la sensación de aplicación profesional).
 */
import Swal, { type SweetAlertResult } from 'sweetalert2';

const COLOR_PRIMARY = '#6B2C8F';
const COLOR_DANGER = '#d93025';
const COLOR_MUTED = '#5f6368';

const baseConfig = {
  confirmButtonColor: COLOR_PRIMARY,
  cancelButtonColor: COLOR_MUTED,
  buttonsStyling: true,
  allowOutsideClick: true,
  allowEscapeKey: true,
  reverseButtons: true,
  focusConfirm: false,
} as const;

/** Aviso simple ("se guardó", "se descargó"). */
export function alertExito(titulo: string, texto?: string) {
  return Swal.fire({
    ...baseConfig,
    icon: 'success',
    title: titulo,
    text: texto,
    confirmButtonText: 'Listo',
    timer: 2500,
    timerProgressBar: true,
  });
}

/** Error duro (no se pudo). */
export function alertError(titulo: string, texto?: string) {
  return Swal.fire({
    ...baseConfig,
    icon: 'error',
    title: titulo,
    text: texto,
    confirmButtonText: 'Entendido',
    confirmButtonColor: COLOR_DANGER,
  });
}

/** Aviso informativo, sin acción. */
export function alertInfo(titulo: string, texto?: string) {
  return Swal.fire({
    ...baseConfig,
    icon: 'info',
    title: titulo,
    text: texto,
    confirmButtonText: 'Entendido',
  });
}

/** Advertencia con un solo botón. */
export function alertWarning(titulo: string, texto?: string) {
  return Swal.fire({
    ...baseConfig,
    icon: 'warning',
    title: titulo,
    text: texto,
    confirmButtonText: 'Entendido',
  });
}

/**
 * Confirmación binaria (¿seguro?). Devuelve true si el usuario confirma.
 * Aceptá un `html` opcional para formateo más rico que `text`.
 */
export async function confirmar(opts: {
  titulo: string;
  texto?: string;
  html?: string;
  textoConfirmar?: string;
  textoCancelar?: string;
  icono?: 'warning' | 'question' | 'info';
}): Promise<boolean> {
  const res: SweetAlertResult = await Swal.fire({
    ...baseConfig,
    icon: opts.icono ?? 'question',
    title: opts.titulo,
    text: opts.html ? undefined : opts.texto,
    html: opts.html,
    showCancelButton: true,
    confirmButtonText: opts.textoConfirmar ?? 'Sí, continuar',
    cancelButtonText: opts.textoCancelar ?? 'Cancelar',
  });
  return res.isConfirmed === true;
}

/**
 * Diálogo de "¿descargar igual? hay una mejor opción". Si el usuario acepta,
 * devuelve `'sugerida'` (usa la sugerencia), `'igual'` (descargar el original)
 * o `null` (canceló).
 */
export async function confirmarConSugerencia(opts: {
  titulo: string;
  texto: string;
  textoSugerido: string;
  textoIgual: string;
}): Promise<'sugerida' | 'igual' | null> {
  const res = await Swal.fire({
    ...baseConfig,
    icon: 'info',
    title: opts.titulo,
    text: opts.texto,
    showCancelButton: true,
    showDenyButton: true,
    confirmButtonText: opts.textoSugerido,
    denyButtonText: opts.textoIgual,
    cancelButtonText: 'Cancelar',
    denyButtonColor: COLOR_MUTED,
  });
  if (res.isConfirmed) return 'sugerida';
  if (res.isDenied) return 'igual';
  return null;
}
