import React from 'react';
import ReactDOM from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';
import { App } from './App.js';
import { AuthProvider } from './lib/auth.js';
import { ErrorBoundary } from './components/ErrorBoundary.js';
import './styles/globals.css';

// Listener global para promesas no manejadas — evita un white screen silencioso
// cuando algo async se cae sin try/catch en alguna página.
window.addEventListener('unhandledrejection', (event) => {
  // eslint-disable-next-line no-console
  console.error('[unhandledRejection]', event.reason);
});

// basename = subpath donde se sirve el SPA (ej: "/Contable-AI" en GitHub Pages).
// Vite expone import.meta.env.BASE_URL respetando la config `base` del build.
// Le sacamos el trailing slash porque React Router lo espera sin él.
const routerBasename = import.meta.env.BASE_URL.replace(/\/$/, '');

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <ErrorBoundary>
      <BrowserRouter basename={routerBasename}>
        <AuthProvider>
          <App />
        </AuthProvider>
      </BrowserRouter>
    </ErrorBoundary>
  </React.StrictMode>,
);
