import { useEffect, useState, type FormEvent } from 'react';
import { Link } from 'react-router-dom';
import { api, ApiError, descargarBlob } from '../lib/api.js';
import { useEmpresa, useEmpresaId } from '../lib/auth.js';
import { formatearCedula, moneda } from '../lib/format.js';
import { Hint } from '../components/Hint.js';
import { LimpiarPanel } from '../components/LimpiarPanel.js';
import { alertError, alertExito, confirmarConSugerencia } from '../lib/alerts.js';

interface SaldoCajaChica {
  empresa_id: string;
  desde: string;
  hasta: string;
  adelantos_abiertos_crc: number;
  facturas_periodo_crc: number;
  cantidad_adelantos: number;
  cantidad_facturas: number;
  saldo: number;
}

function nombreMesLargo(mes: string): string {
  const m = mes.match(/^(\d{4})-(\d{2})$/);
  if (!m) return mes;
  const meses = [
    'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
    'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
  ];
  return `${meses[Number(m[2]) - 1]} de ${m[1]}`;
}

/** ¿El rango desde/hasta es el "infinito" que devuelve el backend cuando no hay filtro? */
function esRangoInfinito(desde: string, hasta: string): boolean {
  return desde.startsWith('0000') || hasta.startsWith('9999');
}

export function CajaChicaPage() {
  const empresa_id = useEmpresaId();
  const empresa = useEmpresa();
  const [saldo, setSaldo] = useState<SaldoCajaChica | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Formulario de adelantos.
  const [monto, setMonto] = useState('');
  const [fecha, setFecha] = useState(() => new Date().toISOString().slice(0, 10));
  const [responsable, setResponsable] = useState('');
  const [notas, setNotas] = useState('');
  const [enviando, setEnviando] = useState(false);
  const [exito, setExito] = useState<string | null>(null);

  // Descarga del Excel.
  const [descargando, setDescargando] = useState(false);
  const [mesExcel, setMesExcel] = useState<string>(() => new Date().toISOString().slice(0, 7));
  // Meses que sí tienen facturas (para sugerencias y bloqueo de descarga vacía).
  const [mesesConDatos, setMesesConDatos] = useState<
    Array<{ mes: string; cantidad: number; total_crc: number }>
  >([]);
  const [mesesCargados, setMesesCargados] = useState(false);

  // Cargar meses disponibles al montar y después de cada acción que modifique la base.
  useEffect(() => {
    let cancelled = false;
    api
      .mesesDisponibles(empresa_id)
      .then((res) => {
        if (cancelled) return;
        setMesesConDatos(res.meses);
        setMesesCargados(true);
        // Si el mes preseleccionado no tiene datos pero hay un mes reciente que sí,
        // adelantamos la sugerencia visualmente.
        if (res.meses.length > 0 && !res.meses.find((m) => m.mes === mesExcel)) {
          // No cambiamos automáticamente — solo lo usamos al descargar.
        }
      })
      .catch(() => {
        // Best-effort. Si falla, sigue funcionando (solo perdemos la sugerencia).
        setMesesCargados(true);
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [empresa_id]);

  function refrescarSaldo() {
    setLoading(true);
    setError(null);
    api
      .saldoCajaChica(empresa_id)
      .then((s) => setSaldo(s))
      .catch((err) => setError(err instanceof ApiError ? err.humano : 'No se pudo cargar el saldo.'))
      .finally(() => setLoading(false));
  }

  useEffect(() => {
    refrescarSaldo();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [empresa_id]);

  async function registrarAdelanto(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setExito(null);
    setError(null);
    const montoNum = Number(monto);
    if (!Number.isFinite(montoNum) || montoNum <= 0) {
      setError('Ingresá un monto válido en colones (mayor a 0).');
      return;
    }
    setEnviando(true);
    try {
      await api.crearAdelanto({
        empresa_id,
        monto_crc: montoNum,
        fecha_entrega: fecha,
        responsable: responsable.trim() || undefined,
        notas: notas.trim() || undefined,
      });
      setExito(`Adelanto de ${moneda(montoNum, 'CRC')} registrado.`);
      setMonto('');
      setResponsable('');
      setNotas('');
      refrescarSaldo();
    } catch (err) {
      setError(err instanceof ApiError ? err.humano : 'No se pudo registrar el adelanto.');
    } finally {
      setEnviando(false);
    }
  }

  /**
   * Descarga el Excel de reintegro, con validaciones para evitar generar un
   * archivo vacío sin querer:
   *   1. Verifica que haya un mes seleccionado.
   *   2. Si el mes elegido NO tiene facturas, ofrece descargar el mes más
   *      reciente con datos (o cancelar). Si el contador insiste, le permite
   *      descargar el vacío (a veces se necesita como "comprobante de que el
   *      mes no tuvo movimientos").
   *   3. Si el mes elegido SÍ tiene datos, descarga directo.
   */
  async function descargarReintegro() {
    if (!mesExcel || !/^\d{4}-\d{2}$/.test(mesExcel)) {
      await alertError(
        'Falta elegir un mes',
        'Seleccioná un mes válido (mes y año) antes de descargar el Excel.',
      );
      return;
    }

    // Solo bloqueamos si ya cargaron los meses disponibles. Si la llamada
    // falló (mesesCargados=true con array vacío) seguimos: capaz la empresa
    // recién arranca y no tiene NADA.
    if (mesesCargados && mesesConDatos.length > 0) {
      const tieneDatos = mesesConDatos.some((m) => m.mes === mesExcel);
      if (!tieneDatos) {
        const sugerido = mesesConDatos[0]!; // ya viene ordenado desc por mes
        const sugeridoNombre = nombreMesLargo(sugerido.mes);
        const elegidoNombre = nombreMesLargo(mesExcel);
        const eleccion = await confirmarConSugerencia({
          titulo: `${elegidoNombre} no tiene facturas`,
          texto: `El mes que elegiste no tiene movimientos cargados. El más reciente con datos es ${sugeridoNombre} (${sugerido.cantidad} factura${sugerido.cantidad === 1 ? '' : 's'}, ${moneda(sugerido.total_crc, 'CRC')}).`,
          textoSugerido: `Descargar ${sugeridoNombre}`,
          textoIgual: `Descargar ${elegidoNombre} igual (vacío)`,
        });
        if (eleccion === null) return;
        if (eleccion === 'sugerida') {
          setMesExcel(sugerido.mes);
          await descargarMes(sugerido.mes);
          return;
        }
        // eleccion === 'igual' → continuamos con el mes vacío
      }
    }

    await descargarMes(mesExcel);
  }

  async function descargarMes(mes: string) {
    setDescargando(true);
    setError(null);
    try {
      const blob = await api.descargarExcelReintegro({
        empresa_id,
        mes,
        saldo: true,
      });
      descargarBlob(blob, `reintegro-caja-chica-${empresa_id}-${mes}.xlsx`);
      await alertExito(
        'Excel descargado',
        `Reintegro de ${nombreMesLargo(mes)} listo. Revisalo en tu carpeta de Descargas.`,
      );
    } catch (err) {
      const msg = err instanceof ApiError ? err.humano : 'No se pudo descargar el Excel.';
      setError(msg);
      await alertError('No se pudo descargar el Excel', msg);
    } finally {
      setDescargando(false);
    }
  }

  return (
    <div className="page">
      <header className="page-header">
        <h1>
          Caja Chica{' '}
          <Hint label="Cómo funciona Caja Chica">
            Registrás un adelanto (efectivo que te dieron) y a medida que subís facturas, el sistema
            las descuenta del saldo. Cuando llega a poco, generás el Excel de Reintegro para pedir
            más fondos.
          </Hint>
        </h1>
        <p className="page-subtitle">
          Saldo líquido = adelanto recibido − facturas del período · Empresa activa: <strong>{empresa.nombre}</strong>{' '}
          <span className="muted small">(céd. {formatearCedula(empresa.id)})</span>.{' '}
          <Link to="/ayuda#caja-chica">¿Cómo funciona Caja Chica? →</Link>
        </p>
      </header>

      {error && <div className="alert alert-error">{error}</div>}

      <section className="card">
        <div className="card-header">
          <h2>Saldo actual</h2>
          <LimpiarPanel
            alcance="todos los adelantos y facturas de caja chica"
            incluirAdelantos
            descripcion="Archivar adelantos y facturas de caja chica. Antes se ofrece un Excel de respaldo."
            onArchivado={() => refrescarSaldo()}
          />
        </div>
        {loading ? (
          <div className="loader-inline"><div className="loader-spinner" /> Cargando…</div>
        ) : saldo ? (
          <div className="grid grid-summary">
            <div>
              <div className="kv-label">Adelantos abiertos</div>
              <div className="kv-value">{moneda(saldo.adelantos_abiertos_crc, 'CRC')}</div>
              <div className="muted small">{saldo.cantidad_adelantos} entregas</div>
            </div>
            <div>
              <div className="kv-label">Facturas del periodo</div>
              <div className="kv-value">{moneda(saldo.facturas_periodo_crc, 'CRC')}</div>
              <div className="muted small">{saldo.cantidad_facturas} facturas</div>
            </div>
            <div>
              <div className="kv-label">Saldo líquido</div>
              <div
                className={`kv-value kv-value-lg ${saldo.saldo >= 0 ? 'kv-value-positive' : 'kv-value-negative'}`}
              >
                {moneda(saldo.saldo, 'CRC')}
              </div>
              <div className="muted small">
                {saldo.saldo >= 0 ? 'Saldo a devolver' : 'Falta reponer'}
              </div>
            </div>
            <div>
              <div className="kv-label">Periodo</div>
              <div className="kv-value kv-value-period">
                {esRangoInfinito(saldo.desde, saldo.hasta) ? 'Todo el historial' : `${saldo.desde} → ${saldo.hasta}`}
              </div>
              <div className="muted small">
                {esRangoInfinito(saldo.desde, saldo.hasta)
                  ? 'Sin filtro de fechas'
                  : 'Filtrado'}
              </div>
            </div>
          </div>
        ) : (
          <p className="muted">Sin datos.</p>
        )}
      </section>

      <section className="card">
        <h2>Registrar adelanto</h2>
        <form className="form-grid" onSubmit={registrarAdelanto}>
          <label className="field">
            <span className="field-label">Monto (CRC)</span>
            <input
              type="number"
              min="0"
              step="0.01"
              value={monto}
              onChange={(e) => setMonto(e.target.value)}
              placeholder="50000"
              required
            />
          </label>
          <label className="field">
            <span className="field-label">Fecha de entrega</span>
            <input
              type="date"
              value={fecha}
              onChange={(e) => setFecha(e.target.value)}
              required
            />
          </label>
          <label className="field">
            <span className="field-label">Responsable</span>
            <input
              type="text"
              value={responsable}
              onChange={(e) => setResponsable(e.target.value)}
              placeholder="Nombre del responsable"
            />
          </label>
          <label className="field field-wide">
            <span className="field-label">Notas</span>
            <input
              type="text"
              value={notas}
              onChange={(e) => setNotas(e.target.value)}
              placeholder="Ej. Adelanto para gastos de oficina semana 2"
            />
          </label>
          <div className="form-actions">
            <button type="submit" className="btn btn-primary" disabled={enviando}>
              {enviando ? 'Registrando…' : 'Registrar adelanto'}
            </button>
            {exito && <span className="text-success">{exito}</span>}
          </div>
        </form>
      </section>

      <section className="card">
        <h2>Descargar Reintegro Caja Chica (Excel)</h2>
        <p className="muted">
          Genera el .xlsx oficial con formato Forward: una fila por (factura × tarifa de IVA),
          totales al pie y saldo líquido = adelantos abiertos − Σ facturas. <strong>El archivo
          contiene solo las facturas del mes que elijas</strong> — si no seleccionás ninguno o
          elegís un mes sin movimientos, el Excel sale vacío.
        </p>
        <div className="filters">
          <label className="field field-inline">
            <span className="field-label">Mes del reporte</span>
            <input
              type="month"
              value={mesExcel}
              onChange={(e) => setMesExcel(e.target.value)}
            />
          </label>
          <span className="muted small">
            Reporte de <strong>{nombreMesLargo(mesExcel)}</strong>
            {mesesCargados && mesesConDatos.length > 0 && (
              mesesConDatos.find((m) => m.mes === mesExcel) ? (
                <span className="badge badge-ok" style={{ marginLeft: 8 }}>
                  con datos ({mesesConDatos.find((m) => m.mes === mesExcel)!.cantidad})
                </span>
              ) : (
                <span className="badge badge-warning" style={{ marginLeft: 8 }}>
                  sin movimientos
                </span>
              )
            )}
          </span>
          <button
            type="button"
            className="btn btn-primary"
            disabled={descargando}
            onClick={descargarReintegro}
          >
            {descargando ? 'Generando…' : 'Descargar Excel'}
          </button>
        </div>

        {mesesCargados && mesesConDatos.length > 0 && (
          <div className="meses-pills" style={{ marginTop: 14 }}>
            <span className="muted small" style={{ marginRight: 8 }}>
              Meses con datos:
            </span>
            {mesesConDatos.slice(0, 8).map((m) => (
              <button
                key={m.mes}
                type="button"
                className={`btn btn-sm ${m.mes === mesExcel ? 'btn-primary' : 'btn-ghost'}`}
                onClick={() => setMesExcel(m.mes)}
                title={`${m.cantidad} factura${m.cantidad === 1 ? '' : 's'} · ${moneda(m.total_crc, 'CRC')}`}
                style={{ marginRight: 6, marginBottom: 6 }}
              >
                {nombreMesLargo(m.mes)} · {m.cantidad}
              </button>
            ))}
          </div>
        )}

        {mesesCargados && mesesConDatos.length === 0 && (
          <div className="alert alert-info" style={{ marginTop: 14 }}>
            Todavía no hay facturas cargadas para esta empresa. Subí algunas desde{' '}
            <Link to="/upload">Subir facturas</Link> y volvé acá a generar el reporte.
          </div>
        )}
      </section>
    </div>
  );
}
